CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE stores(store_id TEXT PRIMARY KEY, merchant_id TEXT NOT NULL UNIQUE, controller_reference TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('draft','published')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, version INTEGER NOT NULL);
CREATE TABLE store_branding(store_id TEXT PRIMARY KEY REFERENCES stores(store_id), avatar_object_id TEXT, banner_object_id TEXT, theme_id TEXT NOT NULL, public_description TEXT NOT NULL, version INTEGER NOT NULL);
CREATE TABLE store_categories(category_id TEXT PRIMARY KEY, store_id TEXT REFERENCES stores(store_id), parent_id TEXT REFERENCES store_categories(category_id), global_taxonomy_id TEXT REFERENCES store_categories(category_id), slug TEXT NOT NULL, sort_order INTEGER NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('public','hidden')), version INTEGER NOT NULL, UNIQUE(store_id,slug));
CREATE UNIQUE INDEX global_category_slug ON store_categories(slug) WHERE store_id IS NULL;
CREATE TABLE media(object_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(store_id), content_hash TEXT NOT NULL, content BLOB NOT NULL, content_type TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE products(product_id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(store_id), canonical_listing_id TEXT, listing_revision INTEGER, metadata_hash TEXT, sku TEXT NOT NULL, description TEXT NOT NULL, media_manifest TEXT NOT NULL, category_id TEXT REFERENCES store_categories(category_id), publish_state TEXT NOT NULL CHECK(publish_state IN ('draft','published')), version INTEGER NOT NULL, UNIQUE(store_id,sku), UNIQUE(canonical_listing_id));
CREATE TABLE product_variants(variant_id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(product_id), option_json TEXT NOT NULL, canonical_listing_id TEXT UNIQUE, variant_sku TEXT NOT NULL, version INTEGER NOT NULL, UNIQUE(product_id,variant_sku));
CREATE TABLE delegates(store_id TEXT NOT NULL REFERENCES stores(store_id), wallet TEXT NOT NULL, controller_reference TEXT NOT NULL, scopes TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(store_id,wallet));
CREATE TABLE auth_nonces(nonce TEXT PRIMARY KEY, wallet TEXT NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE cart_sessions(cart_id TEXT PRIMARY KEY, customer_scope TEXT NOT NULL, store_id TEXT NOT NULL REFERENCES stores(store_id), expires_at INTEGER NOT NULL, version INTEGER NOT NULL);
CREATE TABLE cart_lines(cart_id TEXT NOT NULL REFERENCES cart_sessions(cart_id) ON DELETE CASCADE, listing_id TEXT NOT NULL, requested_revision INTEGER NOT NULL, quantity TEXT NOT NULL, PRIMARY KEY(cart_id,listing_id));
CREATE TABLE checkout_attempts(attempt_id TEXT PRIMARY KEY, cart_id TEXT NOT NULL REFERENCES cart_sessions(cart_id), customer_scope TEXT NOT NULL, merchant_id TEXT NOT NULL, network_id TEXT NOT NULL, order_id TEXT NOT NULL UNIQUE, listing_id TEXT NOT NULL, listing_revision INTEGER NOT NULL, quantity TEXT NOT NULL, seller TEXT NOT NULL, asset TEXT NOT NULL, total TEXT NOT NULL, payment_id TEXT, quote_id TEXT, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, state TEXT NOT NULL, expires_at INTEGER NOT NULL, UNIQUE(customer_scope,merchant_id,network_id,idempotency_key));
CREATE TABLE customer_delivery(order_id TEXT PRIMARY KEY REFERENCES checkout_attempts(order_id), store_id TEXT NOT NULL REFERENCES stores(store_id), encrypted_payload BLOB NOT NULL, access_policy_id TEXT NOT NULL, purge_after INTEGER NOT NULL);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY, actor TEXT NOT NULL, store_id TEXT, operation TEXT NOT NULL, object_id TEXT NOT NULL, occurred_at INTEGER NOT NULL);
CREATE TABLE projection_blocks(height INTEGER PRIMARY KEY, hash TEXT NOT NULL UNIQUE, parent_hash TEXT NOT NULL, finalized INTEGER NOT NULL);
CREATE TABLE event_inbox(event_id TEXT PRIMARY KEY, chain_id TEXT NOT NULL, block_number INTEGER NOT NULL, block_hash TEXT NOT NULL, tx_hash TEXT NOT NULL, tx_index INTEGER NOT NULL, log_index INTEGER NOT NULL, source_contract TEXT NOT NULL, topic TEXT NOT NULL, payload_hash TEXT NOT NULL, payload TEXT NOT NULL, finality TEXT NOT NULL, applied_at INTEGER NOT NULL, canonical INTEGER NOT NULL, UNIQUE(chain_id,block_hash,tx_hash,log_index));
CREATE TABLE projection_checkpoints(chain_id TEXT PRIMARY KEY, stream_version TEXT NOT NULL, cursor TEXT, canonical_block_hash TEXT NOT NULL, height INTEGER NOT NULL, finalized_height INTEGER NOT NULL, schema_version INTEGER NOT NULL, updated_at INTEGER NOT NULL, halted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE catalogue_projection(listing_id TEXT PRIMARY KEY, payload TEXT NOT NULL, block_hash TEXT NOT NULL, block_number INTEGER NOT NULL, finalized INTEGER NOT NULL);
CREATE TABLE order_projection(order_id TEXT PRIMARY KEY, payload TEXT NOT NULL, block_hash TEXT NOT NULL, block_number INTEGER NOT NULL, finalized INTEGER NOT NULL);
CREATE TABLE projection_outbox(id TEXT PRIMARY KEY, event_id TEXT NOT NULL, operation TEXT NOT NULL, payload_ref TEXT NOT NULL, delivered_at INTEGER, attempts INTEGER NOT NULL DEFAULT 0, invalidated INTEGER NOT NULL DEFAULT 0);
CREATE TABLE projection_meta(key TEXT PRIMARY KEY,value INTEGER NOT NULL);
INSERT INTO projection_meta VALUES('generation',0);
